#[test]
fn rq_state_machine_self_transitions_all_rejected() {
    let all = [
        QueueStatus::Pending,
        QueueStatus::Claimed,
        QueueStatus::Rebasing,
        QueueStatus::Testing,
        QueueStatus::ReadyToMerge,
        QueueStatus::Merging,
        QueueStatus::Merged,
        QueueStatus::FailedRetryable,
        QueueStatus::FailedTerminal,
        QueueStatus::Cancelled,
    ];
    for status in &all {
        let result = status.transition_to(*status);
        assert!(
            result.is_err(),
            "Self-transition {:?} -> {:?} should be rejected",
            status,
            status
        );
    }
}

