#[test]
fn rq_priority_ordering_after_dequeue_front() {
    let queue = Queue::new()
        .enqueue(QueueEntry::new("a", "s-a", 10).unwrap())
        .enqueue(QueueEntry::new("b", "s-b", 20).unwrap())
        .enqueue(QueueEntry::new("c", "s-c", 30).unwrap());

    let id_a = QueueEntryId::new("a").unwrap();
    let (queue, removed) = queue.dequeue(&id_a);
    assert!(removed.is_some());
    assert_eq!(queue.len(), 2);

    // Verify ordering preserved after removal
    let priorities: Vec<u32> = queue.entries().iter().map(|e| e.priority).collect();
    for window in priorities.windows(2) {
        assert!(window[0] <= window[1], "Priority ordering violated: {:?}", window);
    }
}

