#[test]
fn rq_fifo_preserved_under_interleaved_operations() {
    // Insert entries with same priority, dequeue middle, re-insert
    let queue = Queue::new()
        .enqueue(QueueEntry::new("a", "s-a", 50).unwrap())
        .enqueue(QueueEntry::new("b", "s-b", 50).unwrap())
        .enqueue(QueueEntry::new("c", "s-c", 50).unwrap());

    let id_b = QueueEntryId::new("b").unwrap();
    let (queue, _) = queue.dequeue(&id_b);

    // Re-insert b at same priority
    let queue = queue.enqueue(QueueEntry::new("b", "s-b", 50).unwrap());

    let ids: Vec<&str> = queue.entries().iter().map(|e| e.id.as_str()).collect();
    // After re-insertion, b should be after c (FIFO within same priority)
    assert_eq!(ids, vec!["a", "c", "b"], "FIFO violated after re-insertion");
}

#[test]
fn rq_priority_invariant_after_many_enqueue_dequeue_cycles() {
    let mut queue = Queue::new();
    for i in 0..100 {
        let id = format!("e-{}", i);
        let session = format!("s-{}", i);
        queue = queue.enqueue(QueueEntry::new(&id, &session, (i % 50) as u32).unwrap());
    }

    // Dequeue every other entry
    for i in 0..100 {
        if i % 2 == 0 {
            let id = QueueEntryId::new(format!("e-{}", i)).unwrap();
            let (q, _) = queue.dequeue(&id);
            queue = q;
        }
    }

    // Verify priority ordering still holds
    let priorities: Vec<u32> = queue.entries().iter().map(|e| e.priority).collect();
    for window in priorities.windows(2) {
        assert!(window[0] <= window[1], "Priority ordering violated after cycles: {:?}", window);
    }
}

#[test]
fn rq_enqueue_at_boundaries_preserves_ordering() {
    let queue = Queue::new()
        .enqueue(QueueEntry::new("min", "s-min", 0).unwrap())
        .enqueue(QueueEntry::new("max", "s-max", MAX_PRIORITY).unwrap())
        .enqueue(QueueEntry::new("mid", "s-mid", 50).unwrap());

    let priorities: Vec<u32> = queue.entries().iter().map(|e| e.priority).collect();
    for window in priorities.windows(2) {
        assert!(window[0] <= window[1]);
    }
    assert_eq!(priorities[0], 0);
    assert_eq!(*priorities.last().unwrap(), MAX_PRIORITY);
}

