#[test]
fn rq_len_matches_entries_after_operations() {
    let mut queue = Queue::new();
    assert_eq!(queue.len(), queue.entries().len());

    for i in 0..20 {
        let id = format!("e-{}", i);
        queue = queue.enqueue(QueueEntry::new(&id, &id, (i % 10) as u32).unwrap());
        assert_eq!(queue.len(), queue.entries().len());
    }

    for i in 0..10 {
        let id = QueueEntryId::new(format!("e-{}", i)).unwrap();
        let (q, _) = queue.dequeue(&id);
        queue = q;
        assert_eq!(queue.len(), queue.entries().len());
    }

    for i in 10..20 {
        let id = QueueEntryId::new(format!("e-{}", i)).unwrap();
        let q = queue.update_status(&id, QueueStatus::Claimed).unwrap();
        queue = q;
        assert_eq!(queue.len(), queue.entries().len());
    }
}

#[test]
fn rq_count_active_vs_manual_count() {
    let merged = QueueEntry::new("c", "s-c", 30)
        .unwrap()
        .transition_status(QueueStatus::Claimed)
        .unwrap()
        .transition_status(QueueStatus::Rebasing)
        .unwrap()
        .transition_status(QueueStatus::Testing)
        .unwrap()
        .transition_status(QueueStatus::ReadyToMerge)
        .unwrap()
        .transition_status(QueueStatus::Merging)
        .unwrap()
        .transition_status(QueueStatus::Merged)
        .unwrap();

    let queue = Queue::new()
        .enqueue(QueueEntry::new("a", "s-a", 10).unwrap())
        .enqueue(
            QueueEntry::new("b", "s-b", 20)
                .unwrap()
                .transition_status(QueueStatus::Claimed)
                .unwrap(),
        )
        .enqueue(merged)
        .enqueue(
            QueueEntry::new("d", "s-d", 40)
                .unwrap()
                .transition_status(QueueStatus::Cancelled)
                .unwrap(),
        );

    let manual_active = queue
        .entries()
        .iter()
        .filter(|e| !e.status.is_terminal())
        .count();

    assert_eq!(queue.count_active(), manual_active);
    assert_eq!(queue.count_active(), 2); // Pending + Claimed
}

#[test]
fn rq_is_empty_consistent_with_len() {
    let queue = Queue::new();
    assert!(queue.is_empty());
    assert_eq!(queue.len(), 0);

    let queue = queue.enqueue(QueueEntry::new("e1", "s1", 10).unwrap());
    assert!(!queue.is_empty());
    assert_eq!(queue.len(), 1);

    let id = QueueEntryId::new("e1").unwrap();
    let (queue, _) = queue.dequeue(&id);
    assert!(queue.is_empty());
    assert_eq!(queue.len(), 0);
}

