#[test]
fn rq_validator_multiple_check_errors() {
    let mut v = Validator::new();
    let _ = v.check(false, ValidationError::EmptyValue("a".into()));
    let _ = v.check(false, ValidationError::EmptyValue("b".into()));
    let _ = v.check(false, ValidationError::EmptyValue("c".into()));
    assert_eq!(v.error_count(), 3);

    let result = v.finalize();
    assert!(matches!(result, Err(ValidationError::Multiple(_))));
    if let Err(ValidationError::Multiple(errors)) = result {
        assert_eq!(errors.len(), 3);
    }
}

