#[test]
fn rq_update_status_invalid_transition_error_details() {
    let queue = Queue::new().enqueue(QueueEntry::new("e1", "s1", 10).unwrap());
    let id = QueueEntryId::new("e1").unwrap();

    let result = queue.update_status(&id, QueueStatus::Merged);
    assert!(matches!(result, Err(ValidationError::InvalidStateTransition { .. })));
    if let Err(ValidationError::InvalidStateTransition { from, to }) = result {
        assert_eq!(from, "pending");
        assert_eq!(to, "merged");
    }
}

#[test]
fn rq_update_status_full_chain() {
    let queue = Queue::new().enqueue(QueueEntry::new("e1", "s1", 10).unwrap());
    let id = QueueEntryId::new("e1").unwrap();

    let chain = [
        QueueStatus::Claimed,
        QueueStatus::Rebasing,
        QueueStatus::Testing,
        QueueStatus::ReadyToMerge,
        QueueStatus::Merging,
        QueueStatus::Merged,
    ];

    let mut queue = queue;
    for status in &chain {
        queue = queue.update_status(&id, *status).unwrap();
    }
    assert_eq!(queue.find(&id).unwrap().status, QueueStatus::Merged);
}

#[test]
fn rq_update_status_failure_then_retry_cycle() {
    let queue = Queue::new().enqueue(QueueEntry::new("e1", "s1", 10).unwrap());
    let id = QueueEntryId::new("e1").unwrap();

    // Fail -> Retry -> Fail -> Retry -> Succeed
    let queue = queue.update_status(&id, QueueStatus::Claimed).unwrap();
    let queue = queue.update_status(&id, QueueStatus::Rebasing).unwrap();
    let queue = queue.update_status(&id, QueueStatus::Testing).unwrap();
    let queue = queue.update_status(&id, QueueStatus::FailedRetryable).unwrap();
    let queue = queue.update_status(&id, QueueStatus::Pending).unwrap();
    let queue = queue.update_status(&id, QueueStatus::Claimed).unwrap();
    let queue = queue.update_status(&id, QueueStatus::Rebasing).unwrap();
    let queue = queue.update_status(&id, QueueStatus::Testing).unwrap();
    let queue = queue.update_status(&id, QueueStatus::ReadyToMerge).unwrap();

    assert_eq!(queue.find(&id).unwrap().status, QueueStatus::ReadyToMerge);
}

