#[test]
fn rq_group_by_status_no_overlap() {
    let queue = Queue::new()
        .enqueue(QueueEntry::new("a", "s-a", 10).unwrap())
        .enqueue(
            QueueEntry::new("b", "s-b", 20)
                .unwrap()
                .transition_status(QueueStatus::Claimed)
                .unwrap(),
        )
        .enqueue(
            QueueEntry::new("c", "s-c", 30)
                .unwrap()
                .transition_status(QueueStatus::Claimed)
                .unwrap()
                .transition_status(QueueStatus::Rebasing)
                .unwrap()
                .transition_status(QueueStatus::Testing)
                .unwrap()
                .transition_status(QueueStatus::ReadyToMerge)
                .unwrap()
                .transition_status(QueueStatus::Merging)
                .unwrap()
                .transition_status(QueueStatus::Merged)
                .unwrap(),
        )
        .enqueue(
            QueueEntry::new("d", "s-d", 40)
                .unwrap()
                .transition_status(QueueStatus::Cancelled)
                .unwrap(),
        );

    let grouped = queue.group_by_status();
    let total: usize = grouped.iter().map(|(_, entries)| entries.len()).sum();
    assert_eq!(total, queue.len());
}

#[test]
fn rq_partition_completeness() {
    let queue = Queue::new()
        .enqueue(QueueEntry::new("a", "s-a", 10).unwrap())
        .enqueue(
            QueueEntry::new("b", "s-b", 20)
                .unwrap()
                .transition_status(QueueStatus::Claimed)
                .unwrap(),
        );

    let (yes, no) = queue.partition(|e| e.status == QueueStatus::Pending);
    assert_eq!(yes.len() + no.len(), queue.len());
}

#[test]
fn rq_sorted_by_key_does_not_mutate_original() {
    let queue = Queue::new()
        .enqueue(QueueEntry::new("c", "s-c", 30).unwrap())
        .enqueue(QueueEntry::new("a", "s-a", 10).unwrap())
        .enqueue(QueueEntry::new("b", "s-b", 20).unwrap());

    // enqueue maintains priority order: a(10), b(20), c(30)
    assert_eq!(queue.entries()[0].id.as_str(), "a");
    assert_eq!(queue.entries()[1].id.as_str(), "b");
    assert_eq!(queue.entries()[2].id.as_str(), "c");

    let _sorted = queue.sorted_by_key(|e| e.priority);

    // sorted_by_key should NOT mutate the original
    assert_eq!(queue.entries()[0].id.as_str(), "a");
    assert_eq!(queue.entries()[1].id.as_str(), "b");
    assert_eq!(queue.entries()[2].id.as_str(), "c");
}

