#[test]
fn rq_queue_entry_serde_with_all_statuses() {
    use chrono::Utc;

    let all_statuses = [
        QueueStatus::Pending,
        QueueStatus::Claimed,
        QueueStatus::Rebasing,
        QueueStatus::Testing,
        QueueStatus::ReadyToMerge,
        QueueStatus::Merging,
        QueueStatus::Merged,
        QueueStatus::FailedRetryable,
        QueueStatus::FailedTerminal,
        QueueStatus::Cancelled,
    ];

    for status in &all_statuses {
        let entry = QueueEntry::with_status(
            QueueEntryId::new("serde-id").unwrap(),
            SessionName::new("serde-session").unwrap(),
            42,
            Utc::now(),
            *status,
        )
        .unwrap();
        let json = serde_json::to_string(&entry).unwrap();
        let back: QueueEntry = serde_json::from_str(&json).unwrap();
        assert_eq!(back.status, *status, "Serde roundtrip failed for {:?}", status);
    }
}

#[test]
fn rq_queue_serde_large_queue() {
    let mut queue = Queue::new();
    for i in 0..200 {
        queue = queue.enqueue(QueueEntry::new(format!("e-{}", i), format!("s-{}", i), (i % 50) as u32).unwrap());
    }
    let json = serde_json::to_string(&queue).unwrap();
    let back: Queue = serde_json::from_str(&json).unwrap();
    assert_eq!(back.len(), queue.len());
}

