#[test]
fn rq_next_pending_returns_lowest_priority_pending() {
    let queue = Queue::new()
        .enqueue(QueueEntry::new("high", "s-high", 50).unwrap())
        .enqueue(QueueEntry::new("low", "s-low", 10).unwrap())
        .enqueue(QueueEntry::new("mid", "s-mid", 30).unwrap());

    let next = queue.next_pending();
    assert!(next.is_some());
    // First pending in priority order should be priority 10
    assert_eq!(next.unwrap().priority, 10);
}

fn make_merged_entry(id: &str, session: &str, priority: u32) -> QueueEntry {
    QueueEntry::new(id, session, priority)
        .unwrap()
        .transition_status(QueueStatus::Claimed)
        .unwrap()
        .transition_status(QueueStatus::Rebasing)
        .unwrap()
        .transition_status(QueueStatus::Testing)
        .unwrap()
        .transition_status(QueueStatus::ReadyToMerge)
        .unwrap()
        .transition_status(QueueStatus::Merging)
        .unwrap()
        .transition_status(QueueStatus::Merged)
        .unwrap()
}

#[test]
fn rq_next_pending_skips_all_non_pending() {
    let queue = Queue::new()
        .enqueue(
            QueueEntry::new("a", "s-a", 10)
                .unwrap()
                .transition_status(QueueStatus::Claimed)
                .unwrap(),
        )
        .enqueue(make_merged_entry("b", "s-b", 20))
        .enqueue(
            QueueEntry::new("c", "s-c", 30)
                .unwrap()
                .transition_status(QueueStatus::Cancelled)
                .unwrap(),
        );

    assert!(queue.next_pending().is_none());
}

#[test]
fn rq_next_pending_after_dequeue_of_first_pending() {
    let queue = Queue::new()
        .enqueue(QueueEntry::new("first", "s-first", 10).unwrap())
        .enqueue(QueueEntry::new("second", "s-second", 20).unwrap());

    let id = QueueEntryId::new("first").unwrap();
    let (queue, _) = queue.dequeue(&id);

    let next = queue.next_pending();
    assert!(next.is_some());
    assert_eq!(next.unwrap().id.as_str(), "second");
}

