// =========================================================================
// DIMENSION: proptest-state-machine-exhaustive
// =========================================================================

mod proptest_red_queen {
    use super::*;
    use proptest::prelude::*;

    proptest! {
        #[test]
        fn prop_rq_transition_result_matches_exhaustive_map(
            from_idx in 0u8..10u8,
            to_idx in 0u8..10u8
        ) {
            let all = [
                QueueStatus::Pending,
                QueueStatus::Claimed,
                QueueStatus::Rebasing,
                QueueStatus::Testing,
                QueueStatus::ReadyToMerge,
                QueueStatus::Merging,
                QueueStatus::Merged,
                QueueStatus::FailedRetryable,
                QueueStatus::FailedTerminal,
                QueueStatus::Cancelled,
            ];
            let from = all[from_idx as usize];
            let to = all[to_idx as usize];

            let result = from.transition_to(to);
            match result {
                Ok(status) => prop_assert_eq!(status, to),
                Err(_) => prop_assert!(true),
            }
        }

        #[test]
        fn prop_rq_immutability_after_any_operation(
            ops in proptest::collection::vec(
                proptest::prop_oneof![
                    proptest::strategy::Just(0u8), // enqueue
                    proptest::strategy::Just(1u8), // dequeue
                ],
                1..20
            ),
        ) {
            let mut queue = Queue::new();
            let mut counter = 0u64;

            for op in &ops {
                match op {
                    0 => {
                        let id = format!("e-{}", counter);
                        let sess = format!("s-{}", counter);
                        counter += 1;
                        if let Ok(entry) = QueueEntry::new(&id, &sess, (counter % 100) as u32) {
                            queue = queue.enqueue(entry);
                        }
                    }
                    1 => {
                        if !queue.is_empty() {
                            if let Some(first) = queue.entries().first() {
                                let id = first.id.clone();
                                let (q, _) = queue.dequeue(&id);
                                queue = q;
                            }
                        }
                    }
                    _ => unreachable!(),
                }

                let len = queue.len();
                prop_assert_eq!(len, queue.entries().len());
            }
        }

        #[test]
        fn prop_rq_priority_ordering_always_sorted(
            entries in proptest::collection::vec(
                (
                    "[a-zA-Z0-9_-]{1,20}",
                    "[a-zA-Z0-9_-]{1,20}",
                    0..=MAX_PRIORITY
                ),
                0..100
            )
        ) {
            let mut queue = Queue::new();
            for (id, session, priority) in &entries {
                if let Ok(entry) = QueueEntry::new(id, session, *priority) {
                    queue = queue.enqueue(entry);
                }
            }

            let priorities: Vec<u32> = queue.entries().iter().map(|e| e.priority).collect();
            for window in priorities.windows(2) {
                prop_assert!(window[0] <= window[1], "Not sorted: {:?} > {:?}", window[0], window[1]);
            }
        }

        #[test]
        fn prop_rq_entry_serde_roundtrip_preserves_all_fields(
            id in "[a-zA-Z0-9_-]{1,20}",
            session in "[a-zA-Z0-9_.-]{1,20}",
            priority in 0..=MAX_PRIORITY,
            status_idx in 0u8..10u8
        ) {
            let all_statuses = [
                QueueStatus::Pending,
                QueueStatus::Claimed,
                QueueStatus::Rebasing,
                QueueStatus::Testing,
                QueueStatus::ReadyToMerge,
                QueueStatus::Merging,
                QueueStatus::Merged,
                QueueStatus::FailedRetryable,
                QueueStatus::FailedTerminal,
                QueueStatus::Cancelled,
            ];

            if let Ok(entry) = QueueEntry::new(&id, &session, priority) {
                let target_status = all_statuses[status_idx as usize];

                let chain = match target_status {
                    QueueStatus::Pending => vec![QueueStatus::Pending],
                    QueueStatus::Claimed => vec![QueueStatus::Claimed],
                    QueueStatus::Rebasing => vec![QueueStatus::Claimed, QueueStatus::Rebasing],
                    QueueStatus::Testing => vec![QueueStatus::Claimed, QueueStatus::Rebasing, QueueStatus::Testing],
                    QueueStatus::ReadyToMerge => vec![QueueStatus::Claimed, QueueStatus::Rebasing, QueueStatus::Testing, QueueStatus::ReadyToMerge],
                    QueueStatus::Merging => vec![QueueStatus::Claimed, QueueStatus::Rebasing, QueueStatus::Testing, QueueStatus::ReadyToMerge, QueueStatus::Merging],
                    QueueStatus::Merged => vec![QueueStatus::Claimed, QueueStatus::Rebasing, QueueStatus::Testing, QueueStatus::ReadyToMerge, QueueStatus::Merging, QueueStatus::Merged],
                    QueueStatus::FailedRetryable => vec![QueueStatus::Claimed, QueueStatus::Rebasing, QueueStatus::Testing, QueueStatus::FailedRetryable],
                    QueueStatus::FailedTerminal => vec![QueueStatus::Claimed, QueueStatus::Rebasing, QueueStatus::Testing, QueueStatus::FailedTerminal],
                    QueueStatus::Cancelled => vec![QueueStatus::Cancelled],
                };

                let mut current = entry;
                for status in chain {
                    let result = current.transition_status(status);
                    match result {
                        Ok(e) => current = e,
                        Err(_) => return Ok(()), // Invalid chain, skip this case
                    }
                }

                let json = serde_json::to_string(&current).unwrap();
                let back: QueueEntry = serde_json::from_str(&json).unwrap();
                prop_assert_eq!(back.id.as_str(), current.id.as_str());
                prop_assert_eq!(back.session.as_str(), current.session.as_str());
                prop_assert_eq!(back.priority, current.priority);
                prop_assert_eq!(back.status, current.status);
            }
        }

        #[test]
        fn prop_rq_queue_len_after_interleaved_ops(
            ops in proptest::collection::vec(
                proptest::prop_oneof![
                    proptest::strategy::Just(0u8), // enqueue
                    proptest::strategy::Just(1u8), // dequeue
                    proptest::strategy::Just(2u8), // remove_at 0
                ],
                1..50
            )
        ) {
            let mut queue = Queue::new();
            let mut counter: u32 = 0;

            for op in &ops {
                match op {
                    0 => {
                        let id = format!("e-{}", counter);
                        let sess = format!("s-{}", counter);
                        counter += 1;
                        if let Ok(entry) = QueueEntry::new(&id, &sess, counter % 100) {
                            queue = queue.enqueue(entry);
                        }
                    }
                    1 => {
                        if !queue.is_empty() {
                            if let Some(first) = queue.entries().first() {
                                let id = first.id.clone();
                                let (q, _) = queue.dequeue(&id);
                                queue = q;
                            }
                        }
                    }
                    2 => {
                        if !queue.is_empty() {
                            let (q, _) = queue.remove_at(0).unwrap();
                            queue = q;
                        }
                    }
                    _ => unreachable!(),
                }
                prop_assert_eq!(queue.len(), queue.entries().len());
            }
        }

        #[test]
        fn prop_rq_validator_collects_correct_error_count(
            errors in proptest::collection::vec(
                proptest::collection::vec("[a-z]{1,5}", 1..5),
                0..10
            )
        ) {
            let mut v = Validator::new();
            let mut expected_count = 0usize;

            for group in &errors {
                if group.is_empty() {
                    continue;
                }
                for name in group {
                    v.add_error(ValidationError::EmptyValue(name.clone()));
                    expected_count += 1;
                }
            }

            prop_assert_eq!(v.error_count(), expected_count);

            let result = v.finalize();
            if expected_count == 0 {
                prop_assert!(result.is_ok());
            } else if expected_count == 1 {
                prop_assert!(result.is_err());
                prop_assert!(!matches!(result, Err(ValidationError::Multiple(_))));
            } else {
                prop_assert!(matches!(result, Err(ValidationError::Multiple(_))));
                if let Err(ValidationError::Multiple(errs)) = result {
                    prop_assert_eq!(errs.len(), expected_count);
                }
            }
        }
    }
}
